const item = $input.first().json;

// n8n may nest JSON under body depending on version
const body = item.body && typeof item.body === 'object' ? item.body : item;
const userId = body.user_id || item.user_id;
const resumeText = String(body.resume_text || item.resume_text || '').trim();

if (!userId) {
  throw new Error('Missing user_id');
}
if (!resumeText) {
  throw new Error('Missing resume_text');
}

// Cap input so the OpenAI call stays small
const MAX = 20000;
const clipped =
  resumeText.length <= MAX
    ? resumeText
    : resumeText.slice(0, MAX).trimEnd() + '\n…[truncated]';

return [{
  json: {
    user_id: userId,
    resume_text: clipped,
  },
}];

const ai = $input.first().json;
const prepared = $('Prepare Payload').first().json;

const raw =
  ai.choices?.[0]?.message?.content ||
  ai.message?.content ||
  ai.content ||
  '';

let text = String(raw).trim();
text = text
  .replace(/^```(?:markdown|md)?\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

if (!text) {
  throw new Error('OpenAI returned empty markdown');
}

// Soft cap aligned with app RESUME_TEXT_MAX_CHARS
const MAX = 8000;
if (text.length > MAX) {
  text = text.slice(0, MAX).trimEnd() + '\n…[truncated]';
}

return [{
  json: {
    user_id: prepared.user_id,
    resume_text: text,
    characters: text.length,
  },
}];

const result = $input.first().json;
const parsed = $('Parse Markdown').first().json;

console.log('Resume normalize complete');
console.log(`user_id: ${parsed.user_id}`);
console.log(`characters: ${parsed.characters}`);

return [{
  json: {
    summary: 'Resume normalized to markdown and saved.',
    user_id: parsed.user_id,
    characters: parsed.characters,
    api: result,
    timestamp: new Date().toISOString(),
  },
}];
